// Invented records only. Expected outcomes are hand-derived, not generated by
// the evaluator. This packet abstracts semantics; it is not the persisted v2 schema.
const hash = 'a'.repeat(64);
const entry = (id = 'irl:synthetic:one', extra = {}) => ({
  id, version: 2, kind: 'interpretation',
  event_start: '2030-01-02', event_end: '2030-01-02',
  evidence_as_of: '2030-01-04', recorded_at: '2030-01-05T12:00:00Z',
  learned_at: null, learning_basis: null,
  interpreter_id: 'synthetic-analyst', participant_authored: false,
  activates_work: false, publication_authorized: false,
  relations: [{ type: 'about', target: 'node:synthetic:project' }],
  citations: [{ source_id: 'source:synthetic:one', revision: '1', sha256: hash,
    locator: 'lines 1-3', evidence_class: 'attributed-report' }],
  ...extra
});
const packet = () => ({
  visibility: 'private', requested_effect: 'review',
  recorded_as_of: '2030-01-10T12:00:00Z', occurred_by: '2030-01-10',
  history_conflict: false,
  nodes: [{ id: 'node:synthetic:project', type: 'project', visibility: 'private' }],
  sources: [{ id: 'source:synthetic:one', revision: '1', sha256: hash,
    evidence_class: 'attributed-report', issued_on: '2030-01-04',
    captured_at: '2030-01-05T11:00:00Z', state: 'current' }],
  entries: [entry()]
});
const result = (decision, reasons = [], entries = []) => ({
  decision, reasons, entries,
  implementation_authorized: false, migration_authorized: false,
  publication_authorized: false, activates_work: false
});
const visible = (id = 'irl:synthetic:one', status = 'recorded', learned_at = null) => ({
  id, status, learned_at, historical_reconstruction: true
});
const ready = (entries = [visible()]) => result('ready-for-human-review', [], entries);
const deny = (reason) => result('deny', [reason]);
const hold = (reason, entries = [visible()]) => result('hold', [reason], entries);
const example = (id, change, expected) => {
  const input = packet();
  change(input);
  return { id, packet: input, expected };
};
const later = (kind, type) => entry('irl:synthetic:two', {
  kind, recorded_at: '2030-01-07T12:00:00Z',
  relations: [{ type: 'about', target: 'node:synthetic:project' },
    { type, target: 'irl:synthetic:one' }]
});

export const cases = [
  example('private-reading-is-review-not-action', () => {}, ready()),
  example('late-recovery-does-not-exist-in-earlier-record-view', p => {
    p.recorded_as_of = '2030-01-04T12:00:00Z';
  }, ready([])),
  example('later-development-does-not-correct-previous-account', p => {
    p.entries.push(later('development', 'updates'));
  }, ready([visible('irl:synthetic:one', 'updated'), visible('irl:synthetic:two')])),
  example('correction-preserves-earlier-entry', p => {
    p.entries.push(later('correction', 'corrects'));
  }, ready([visible('irl:synthetic:one', 'corrected'), visible('irl:synthetic:two')])),
  example('earlier-view-does-not-see-later-correction', p => {
    p.entries.push(later('correction', 'corrects'));
    p.recorded_as_of = '2030-01-06T12:00:00Z';
  }, ready()),
  example('challenge-remains-contested-not-settled', p => {
    p.entries.push(later('challenge', 'challenges'));
  }, hold('contested-reading', [visible('irl:synthetic:one', 'contested'), visible('irl:synthetic:two')])),
  example('correction-needs-explicit-prior-target', p => {
    p.entries[0].kind = 'correction';
  }, deny('revision-kind-mismatch')),
  example('development-cannot-assert-correction', p => {
    p.entries.push(later('development', 'corrects'));
  }, deny('revision-kind-mismatch')),
  example('self-reference-is-not-a-valid-revision', p => {
    p.entries[0].kind = 'correction';
    p.entries[0].relations.push({ type: 'corrects', target: 'irl:synthetic:one' });
  }, deny('revision-target-not-prior')),
  example('missing-graph-node-is-not-a-resolved-link', p => {
    p.entries[0].relations[0].target = 'node:synthetic:missing';
  }, deny('unresolved-relation')),
  example('claim-is-not-an-about-person-or-project-edge', p => {
    p.nodes[0].type = 'claim';
  }, deny('wrong-relation-target-type')),
  example('unknown-relation-fails-closed', p => {
    p.entries[0].relations[0].type = 'endorses';
  }, deny('unknown-relation')),
  example('duplicate-entry-id-is-not-overwritten', p => {
    p.entries.push(entry());
  }, deny('duplicate-entry-id')),
  example('legacy-schema-requires-explicit-migration', p => {
    p.entries[0].version = 1;
  }, deny('unsupported-entry-version')),
  example('local-sequence-is-not-global-identity', p => {
    p.entries[0].id = 'IRL-0001';
  }, deny('unnamespaced-entry-id')),
  example('source-revision-mismatch-is-not-current-evidence', p => {
    p.entries[0].citations[0].sha256 = 'b'.repeat(64);
  }, deny('unbound-source-revision')),
  example('summary-cannot-be-promoted-to-direct-evidence', p => {
    p.entries[0].citations[0].evidence_class = 'primary-record';
  }, deny('unbound-source-revision')),
  example('missing-citation-does-not-pass-review', p => {
    p.entries[0].citations = [];
  }, deny('missing-citation')),
  example('changed-source-marks-dependent-reading-stale', p => {
    p.sources[0].state = 'changed';
  }, hold('source-not-current', [visible('irl:synthetic:one', 'stale')])),
  example('unavailable-source-does-not-certify-freshness', p => {
    p.sources[0].state = 'unavailable';
  }, hold('source-not-current', [visible('irl:synthetic:one', 'stale')])),
  example('withdrawn-source-withholds-reading', p => {
    p.sources[0].state = 'withdrawn';
  }, hold('retention-review-required', [visible('irl:synthetic:one', 'withheld')])),
  example('invalid-calendar-date-is-not-normalized', p => {
    p.entries[0].event_start = '2030-02-30';
  }, deny('invalid-chronology')),
  example('source-capture-cannot-postdate-recording', p => {
    p.sources[0].captured_at = '2030-01-06T12:00:00Z';
  }, deny('invalid-chronology')),
  example('unknown-learning-time-is-not-event-time', () => {}, ready()),
  example('claimed-learning-needs-a-cited-basis', p => {
    p.entries[0].learned_at = '2030-01-04T12:00:00Z';
  }, deny('unbound-learning-time')),
  example('unknown-event-window-stays-visible-as-uncertain', p => {
    p.entries[0].event_start = null;
    p.entries[0].event_end = null;
  }, hold('unknown-event-time', [{ ...visible(), historical_reconstruction: null }])),
  example('public-request-reveals-no-private-identifiers', p => {
    p.visibility = 'public';
  }, deny('public-journal-export-forbidden')),
  example('recording-cannot-activate-a-commitment', p => {
    p.entries[0].activates_work = true;
  }, deny('authority-promotion')),
  example('requesting-external-action-does-not-execute-it', p => {
    p.requested_effect = 'send';
  }, deny('authority-promotion')),
  example('analysis-is-not-participant-authored-voice', p => {
    p.entries[0].participant_authored = true;
  }, deny('participant-impersonation')),
  example('divergent-history-requires-reviewed-rebase', p => {
    p.history_conflict = true;
  }, hold('history-conflict', [])),
  example('later-correction-does-not-silently-resolve-a-challenge', p => {
    p.entries.push(later('challenge', 'challenges'));
    p.entries.push({ ...later('correction', 'corrects'), id: 'irl:synthetic:three' });
  }, hold('contested-reading', [visible('irl:synthetic:one', 'contested'),
    visible('irl:synthetic:two'), visible('irl:synthetic:three')])),
  example('later-development-does-not-erase-a-correction-warning', p => {
    p.entries.push(later('correction', 'corrects'));
    p.entries.push({ ...later('development', 'updates'), id: 'irl:synthetic:three' });
  }, ready([visible('irl:synthetic:one', 'corrected'),
    visible('irl:synthetic:two'), visible('irl:synthetic:three')]))
];
